// Turn the USDA answer into one short text for the AI
const asked = ($('Set food').first().json.food || '').trim().toLowerCase();
if (!asked) {
  return [{ json: { data: "NO_FOOD: add ?food=<food name in English> to the URL." } }];
}
const foods = $json.foods || [];
// pick the best match. "apples raw" must give "Apples, raw, with skin", not "Rose-apples, raw":
// +10 if the name starts with the first word, +3 for each word found, and simpler (shorter) names first
const words = asked.replace(/,/g, ' ').split(/\s+/).filter(Boolean).map(w => w.replace(/s$/, ''));
const score = f => {
  const d = f.description.toLowerCase().replace(/,/g, ' ');
  let s = d.split(/\s+/)[0].startsWith(words[0]) ? 10 : 0;
  s += words.filter(w => d.includes(w)).length * 3;
  return s - d.length / 100;
};
const food = foods.slice().sort((a, b) => score(b) - score(a))[0];
if (!food) {
  return [{ json: { data: `NOT_FOUND: no food called "${asked}" in USDA FoodData Central. Try a simpler English name.` } }];
}
const get = (name, unit) => {
  const n = (food.foodNutrients || []).find(x =>
    x.nutrientName.startsWith(name) && (!unit || (x.unitName || "").toUpperCase() === unit));
  return n ? `${n.value} ${(n.unitName || "").toLowerCase()}` : "?";
};
const text = `${food.description} (per 100 g): ` +
  `energy ${get("Energy", "KCAL")}, protein ${get("Protein")}, fat ${get("Total lipid")}, ` +
  `carbs ${get("Carbohydrate")}, sugars ${get("Total Sugars")}, fiber ${get("Fiber")}, ` +
  `sodium ${get("Sodium")}. Source: USDA FoodData Central (fdc.nal.usda.gov)`;
return [{ json: { data: text } }];
